[ClassInitialize]
public static void ClassSetup(TestContext context)
{
    // In MSTest v4, TestContext passed to ClassInitialize no longer
    // exposes per-test properties like TestName (the class-level context
    // runs before any test method is selected). Use only class-level
    // information here; access TestName in [TestInitialize] or via the
    // instance TestContext property instead.
    var name = context.FullyQualifiedTestClassName;
    System.Console.WriteLine($"Setting up for: {name}");
}

